<?php
require __DIR__.'/../app/bootstrap.php';require_admin();$id=(int)($_GET['activity']??0);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="workshop-interest-submissions.csv"');echo "\xEF\xBB\xBF";$fields=array_column(interest_form_definition()['fields'],'id');$out=fopen('php://output','w');fputcsv($out,array_merge(['id','activity','slug','created_at','name','email','country'],$fields));$q=database()->prepare('SELECT i.*,a.admin_name,a.slug FROM interest_submissions i LEFT JOIN activities a ON a.id=i.activity_id'.($id?' WHERE i.activity_id=?':'').' ORDER BY i.id DESC');$q->execute($id?[$id]:[]);foreach($q as $r){$payload=json_decode($r['payload_json'],true)?:[];$line=[$r['id'],$r['admin_name'],$r['slug'],$r['created_at'],$r['name'],$r['email'],$r['country']];foreach($fields as $field)$line[]=$payload[$field]??'';fputcsv($out,$line);}
